public static Yaf_LoaderfalseYaf_Loader::getInstance stringlocal_library_pathnull stringglobal_library_pathnull
Récupère l'instance unique (singleton) de Yaf_Loader. Si les chemins des bibliothèques sont fournis, ils sont appliqués à l'instance existante.

  &reftitle.examples;

   Exemple avec Yaf_Loader::getInstance


<?php
$app = new Yaf_Application(__DIR__ . "/conf/application.ini");

/* Yaf_Application a initialisé le chargeur, l'instance
 * unique est donc désormais disponible */
$loader = Yaf_Loader::getInstance();
$loader->registerNamespace("Vendor", APPLICATION_PATH . "/library/Vendor");
?>




   Yaf_Loader::getInstance avant l'initialisation


<?php
/* aucune Yaf_Application n'a encore été créée */
var_dump(Yaf_Loader::getInstance());
?>


   &example.outputs.similar;


